(1148017, 142540, 14671, '<td valign="top">hahaha  this is about the third photo I''ve seen with some humour to it.  Nice B&amp;W , great clarity and contrast.  Well done and good luck in this challenge. &lt;8&gt;</td>', 'hahaha  this is about the third photo I''ve seen with some humour to it.  Nice B&W , great clarity and contrast.  Well done and good luck in this challenge. <8>', '2005-02-02 23:17:06.000000', NULL, 1),
(1148018, 142161, 14671, '<td valign="top">Nicely done.  The graininess of the shot goes well with the B&amp;W.  The over contrast of the sky also goes well with the shot.  Well done and good luck in this challenge. &lt;7&gt;</td>', 'Nicely done.  The graininess of the shot goes well with the B&W.  The over contrast of the sky also goes well with the shot.  Well done and good luck in this challenge. <7>', '2005-02-02 23:18:18.000000', NULL, 1),
