(1148098, 141521, 31440, '<td valign="top">Nice use of shadow...</td>', 'Nice use of shadow...', '2005-02-03 00:30:23.000000', NULL, 1),
(1148099, 140907, 5728, '<td valign="top">I guess you can only find something like this in the USA. Funny :)</td>', 'I guess you can only find something like this in the USA. Funny :)', '2005-02-03 00:32:10.000000', NULL, 1),
(1148100, 141631, 25261, '<td valign="top">Noooooo! Not the clamps!  Thanks, this is good.</td>', 'Noooooo! Not the clamps!  Thanks, this is good.', '2005-02-03 00:32:35.000000', NULL, 1),
(1148101, 142181, 5728, '<td valign="top">Interesting angle. The power lines are a little bothersome though, and I would have tried to get a little more light onto the sign, especially the top part to make it jump out more.</td>', 'Interesting angle. The power lines are a little bothersome though, and I would have tried to get a little more light onto the sign, especially the top part to make it jump out more.', '2005-02-03 00:33:27.000000', NULL, 1),
(1148103, 140126, 5728, '<td valign="top">Nice shot. Although the background is cluttered with powerlines etc, it isn''t all that noticeable due to the desaturation. Like it :)</td>', 'Nice shot. Although the background is cluttered with powerlines etc, it isn''t all that noticeable due to the desaturation. Like it :)', '2005-02-03 00:34:25.000000', NULL, 1),
(1148104, 142473, 5728, '<td valign="top">Funny :)</td>', 'Funny :)', '2005-02-03 00:34:36.000000', NULL, 1),
(1148105, 141656, 5728, '<td valign="top">I''d love to live on Love Lane :) Good eye!</td>', 'I''d love to live on Love Lane :) Good eye!', '2005-02-03 00:35:25.000000', NULL, 1),
(1148106, 141824, 5728, '<td valign="top">Busy busy busy! I would have taken the number plates off my car, put a mask on and tried to drive past getting a 99 number on that radar display, and then take the photo :)</td>', 'Busy busy busy! I would have taken the number plates off my car, put a mask on and tried to drive past getting a 99 number on that radar display, and then take the photo :)', '2005-02-03 00:37:02.000000', NULL, 1),
(1148107, 142251, 5728, '<td valign="top">Funny :)</td>', 'Funny :)', '2005-02-03 00:37:13.000000', NULL, 1),
(1148108, 142441, 25261, '<td valign="top">Interesting. Please tell the tale.</td>', 'Interesting. Please tell the tale.', '2005-02-03 00:37:25.000000', NULL, 1),
(1148109, 142198, 5728, '<td valign="top">Powerful message! Good idea.</td>', 'Powerful message! Good idea.', '2005-02-03 00:37:47.000000', NULL, 1),
(1148113, 142260, 25261, '<td valign="top">Basic editing? How?</td>', 'Basic editing? How?', '2005-02-03 00:40:20.000000', NULL, 1),
