INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1148553, 141834, 23053, '<td valign="top">I would like to see this shot redone with just the sign and the sky...it may have required a different vantage point, though, to eliminate the building and plants in the background...but hey, I get the feeling you know what you are up to.</td>', 'I would like to see this shot redone with just the sign and the sky...it may have required a different vantage point, though, to eliminate the building and plants in the background...but hey, I get the feeling you know what you are up to.', '2005-02-03 08:45:21.000000', NULL, 1),
(1148571, 140989, 14671, '<td valign="top">Nicely timed.  Perhaps a little to bright tho but does have good clarity and crispness.  Good luck in this challenge.</td>', 'Nicely timed.  Perhaps a little to bright tho but does have good clarity and crispness.  Good luck in this challenge.', '2005-02-03 09:10:21.000000', NULL, 1),
(1148574, 141269, 14671, '<td valign="top">Beautfil DoF and excellent crispness on the sign.  It goes well with the lights in the background.  Perhaps taking an inch off the right side to make it more centered (if you will) would have made for a better picture and reduced he amount of grey that you see.  I think it would have drawn the eye more into the photo as well.  Good job and good luck in this challenge.  &lt;7&gt;</td>', 'Beautfil DoF and excellent crispness on the sign.  It goes well with the lights in the background.  Perhaps taking an inch off the right side to make it more centered (if you will) would have made for a better picture and reduced he amount of grey that you see.  I think it would have drawn the eye more into the photo as well.  Good job and good luck in this challenge.  <7>', '2005-02-03 09:13:13.000000', NULL, 1),
(1148576, 142459, 3569, '<td valign="top">Wow where is your snow! Drought still?  Nice shot though</td>', 'Wow where is your snow! Drought still?  Nice shot though', '2005-02-03 09:17:43.000000', NULL, 1),
(1148577, 142419, 14671, '<td valign="top">Excellent choice of DoF and great clarity.  A little brightness would have done a lot for tihs photo.  well done and good luck in this challenge.  &lt;7&gt;</td>', 'Excellent choice of DoF and great clarity.  A little brightness would have done a lot for tihs photo.  well done and good luck in this challenge.  <7>', '2005-02-03 09:17:45.000000', NULL, 1),
(1148578, 141249, 3569, '<td valign="top">Rye?</td>', 'Rye?', '2005-02-03 09:20:07.000000', NULL, 1),
(1148579, 142238, 14671, '<td valign="top">Not that I''m fond of religious photo''s the brightness of the background makes it appear to have to high of contrast and be a little to bright.  I also find it not to have very good clarity or focus.  Perhaps if it weren''t so close or upward looking would have been a better shot.  Good luck in this challenge.</td>', 'Not that I''m fond of religious photo''s the brightness of the background makes it appear to have to high of contrast and be a little to bright.  I also find it not to have very good clarity or focus.  Perhaps if it weren''t so close or upward looking would have been a better shot.  Good luck in this challenge.', '2005-02-03 09:21:01.000000', NULL, 1),
