(1148715, 142710, 19066, '<td valign="top">Nice pic.  If only it was larger!</td>', 'Nice pic.  If only it was larger!', '2005-02-03 10:56:26.000000', NULL, 1),
(1148719, 141864, 14476, '<td valign="top">I keep coming back to this one.  Great originality, and good colors.  Be careful when you do this kind of photography.  (you probably know)  It''s tough on your eyes.  Take care!</td>', 'I keep coming back to this one.  Great originality, and good colors.  Be careful when you do this kind of photography.  (you probably know)  It''s tough on your eyes.  Take care!', '2005-02-03 10:59:53.000000', NULL, 1),
(1148722, 141629, 14476, '<td valign="top">You have captured the bleakness of this historic spot beautifully.   Still, just a little more saturation of colors would have made this image pop nicely.  Good luck in whatever you are doing that takes you to this place this week.</td>', 'You have captured the bleakness of this historic spot beautifully.   Still, just a little more saturation of colors would have made this image pop nicely.  Good luck in whatever you are doing that takes you to this place this week.', '2005-02-03 11:02:40.000000', NULL, 1),
