INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1149801, 142102, 19780, '<td valign="top">I like this shot, I think it''s well composed, I like the off centered subject and the perspective of the line of the road going off into the distance. However, it''s posed and feels forced in a way. I think it could have been more powerful if it felt more natural - a hitchhiker doesn''t sit in the middle of the road, after all. Nicely executed. 6</td>', 'I like this shot, I think it''s well composed, I like the off centered subject and the perspective of the line of the road going off into the distance. However, it''s posed and feels forced in a way. I think it could have been more powerful if it felt more natural - a hitchhiker doesn''t sit in the middle of the road, after all. Nicely executed. 6', '2005-02-03 22:57:19.000000', NULL, 1),
(1149808, 142102, 29513, '<td valign="top">Nice idea well executed.</td>', 'Nice idea well executed.', '2005-02-03 23:03:16.000000', NULL, 1),
