(1150990, 142710, 16301, '<td valign="top">Too bad, this would have looked great in 640 pixels...</td>', 'Too bad, this would have looked great in 640 pixels...', '2005-02-04 17:44:04.000000', NULL, 1),
(1150997, 142702, 32792, '<td valign="top">Nice lighting! I like the way the tail lights look!<br/>My guess is that waldo was in a hurry! (8)</td>', 'Nice lighting! I like the way the tail lights look!My guess is that waldo was in a hurry! (8)', '2005-02-04 17:48:37.000000', NULL, 1),
(1151035, 141505, 26679, '<td valign="top">This is a great tram, I only wish the wording on the signs were a little more clear.</td>', 'This is a great tram, I only wish the wording on the signs were a little more clear.', '2005-02-04 18:15:47.000000', NULL, 1),
