(1151091, 142572, 4226, '<td valign="top">children sure have advanced, they now play with snow mobiles</td>', 'children sure have advanced, they now play with snow mobiles', '2005-02-04 18:52:02.000000', NULL, 1),
(1151094, 140907, 4226, '<td valign="top">this is funny</td>', 'this is funny', '2005-02-04 18:53:41.000000', NULL, 1),
(1151102, 142420, 32507, '<td valign="top">I really like this photo.  The one thing I think that could be changed is the lighting on the actual street sign, seems a bit reflective for this photo.  I do like the light coming off the building it creates an effect that reminds me of how streetlights are drawn in comic books (if that makes any sense to you).  The shadows are great.</td>', 'I really like this photo.  The one thing I think that could be changed is the lighting on the actual street sign, seems a bit reflective for this photo.  I do like the light coming off the building it creates an effect that reminds me of how streetlights are drawn in comic books (if that makes any sense to you).  The shadows are great.', '2005-02-04 19:12:59.000000', NULL, 1),
(1151105, 142421, 32513, '<td valign="top">The bottom half of this picture is blown out. I don''t know yet how you took this picture, but from the looks of it, I think your camera meter was badly fooled by the tire. This caused the camera to get a good exposure for the tire, but ultimatly you practically lost all detail in the brighter areas of the image. Be carefull of high contrast situations like this. It''s best to use a meter reading off of the subject, or, if you can, use an 18% gray card.</td>', 'The bottom half of this picture is blown out. I don''t know yet how you took this picture, but from the looks of it, I think your camera meter was badly fooled by the tire. This caused the camera to get a good exposure for the tire, but ultimatly you practically lost all detail in the brighter areas of the image. Be carefull of high contrast situations like this. It''s best to use a meter reading off of the subject, or, if you can, use an 18% gray card.', '2005-02-04 19:14:51.000000', NULL, 1),
(1151111, 140975, 16106, '<td valign="top">As a pure graphic this is one of the best in the challenge, I wish you hadn''t squeezed the sign so much that the arms ran off the page, but the forms and colors are very strong.</td>', 'As a pure graphic this is one of the best in the challenge, I wish you hadn''t squeezed the sign so much that the arms ran off the page, but the forms and colors are very strong.', '2005-02-04 19:21:52.000000', NULL, 1),
(1151112, 142716, 32513, '<td valign="top">Watch your exposure! The sky is very blown out.</td>', 'Watch your exposure! The sky is very blown out.', '2005-02-04 19:22:28.000000', NULL, 1),
(1151113, 142717, 12571, '<td valign="top">did not fit challenge theme</td>', 'did not fit challenge theme', '2005-02-04 19:22:48.000000', NULL, 1),
(1151114, 141309, 12571, '<td valign="top">i felt that this was gratuitous and vulgar</td>', 'i felt that this was gratuitous and vulgar', '2005-02-04 19:23:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1151115, 140612, 12571, '<td valign="top">did not fit challenge theme</td>', 'did not fit challenge theme', '2005-02-04 19:23:42.000000', NULL, 1),
(1151116, 142588, 32513, '<td valign="top">This is a good start, but it would be much better if the bottom of the sign wasn''t so washed out. I''m betting thats because of you''re flash. Try a different angle.</td>', 'This is a good start, but it would be much better if the bottom of the sign wasn''t so washed out. I''m betting thats because of you''re flash. Try a different angle.', '2005-02-04 19:23:50.000000', NULL, 1),
(1151117, 141519, 12571, '<td valign="top">lack of signs does not make it fit theme, no matter how tongue in cheek it may be</td>', 'lack of signs does not make it fit theme, no matter how tongue in cheek it may be', '2005-02-04 19:24:29.000000', NULL, 1),
(1151122, 142563, 16106, '<td valign="top">If this is the sign near San Gabriel it is the one I wanted to shoot for this challenge ( as well as visit the seals at point lobos)  but failed to do so.. Great location, and you did a great job isolating the sign and the wave.  IMHO it might have been improved by getting the sign bigger in the frame, a bit more punch in the colors, either by shooting in the morning with the sun behind you, or in the evening with flash fill, and lastly the narrow strip of sky is distracting, either go lower and get more of the sky, or go higher and get all ocean and sign. On balance a very nice shot 7</td>', 'If this is the sign near San Gabriel it is the one I wanted to shoot for this challenge ( as well as visit the seals at point lobos)  but failed to do so.. Great location, and you did a great job isolating the sign and the wave.  IMHO it might have been improved by getting the sign bigger in the frame, a bit more punch in the colors, either by shooting in the morning with the sun behind you, or in the evening with flash fill, and lastly the narrow strip of sky is distracting, either go lower and get more of the sky, or go higher and get all ocean and sign. On balance a very nice shot 7', '2005-02-04 19:29:14.000000', NULL, 1),
(1151124, 142668, 16106, '<td valign="top">This is a boring idea executed so well it is audacious. The square format and the diagonal framing work amazingly well. Lovely geometry, you win the ribbon for the bravest entrant.</td>', 'This is a boring idea executed so well it is audacious. The square format and the diagonal framing work amazingly well. Lovely geometry, you win the ribbon for the bravest entrant.', '2005-02-04 19:31:48.000000', NULL, 1),
(1151125, 140883, 16106, '<td valign="top">On further review this is too sweet a shot for a 7 you get the bump to eight for great restrained color control and perfect DOF</td>', 'On further review this is too sweet a shot for a 7 you get the bump to eight for great restrained color control and perfect DOF', '2005-02-04 19:33:29.000000', NULL, 1),
(1151127, 142538, 16106, '<td valign="top">This shot has all the elements of a winner almost perfectly lit and exposed. I ecpect this to do very well, if only there was a bit more light on the right edge it would be poster quality. It feels like the open road, and makes me wish I were there.</td>', 'This shot has all the elements of a winner almost perfectly lit and exposed. I ecpect this to do very well, if only there was a bit more light on the right edge it would be poster quality. It feels like the open road, and makes me wish I were there.', '2005-02-04 19:36:45.000000', NULL, 1),
(1151128, 141244, 16106, '<td valign="top">fine concept and framing but more light more color more pop. Almost there.</td>', 'fine concept and framing but more light more color more pop. Almost there.', '2005-02-04 19:38:24.000000', NULL, 1),
(1151132, 142619, 16106, '<td valign="top">I very much like this shot but I find the wire the fly in the soup. Had you been able to clone them out, or if you had gotten some sort of distraction like a bike or truck blurring by in front of the wire, that would have pushed this into the top ten. other than that one isuue a great job.</td>', 'I very much like this shot but I find the wire the fly in the soup. Had you been able to clone them out, or if you had gotten some sort of distraction like a bike or truck blurring by in front of the wire, that would have pushed this into the top ten. other than that one isuue a great job.', '2005-02-04 19:41:22.000000', NULL, 1),
(1151159, 142708, 4793, '<td valign="top">Cute name for a road sign, nice work.</td>', 'Cute name for a road sign, nice work.', '2005-02-04 20:28:34.000000', NULL, 1),
