(1151619, 141674, 24212, '<td valign="top">Amusing sign, pity about the overcast day.</td>', 'Amusing sign, pity about the overcast day.', '2005-02-05 05:05:47.000000', NULL, 1),
(1151620, 142459, 24212, '<td valign="top">Extremely dramatic. I guess you used a polariser.</td>', 'Extremely dramatic. I guess you used a polariser.', '2005-02-05 05:06:44.000000', NULL, 1),
(1151622, 142422, 24212, '<td valign="top">If it were me, I''d rotate this slightly, so that the post is vertical.</td>', 'If it were me, I''d rotate this slightly, so that the post is vertical.', '2005-02-05 05:08:33.000000', NULL, 1),
(1151623, 141982, 24212, '<td valign="top">Lovely and bright, although it may be a touch oversaturated. Neat framing.</td>', 'Lovely and bright, although it may be a touch oversaturated. Neat framing.', '2005-02-05 05:09:34.000000', NULL, 1),
(1151626, 141531, 24212, '<td valign="top">Very ''Day After Tomorrow''. The ice on the pole looks a little overexposed, though.</td>', 'Very ''Day After Tomorrow''. The ice on the pole looks a little overexposed, though.', '2005-02-05 05:13:29.000000', NULL, 1),
(1151628, 141385, 24212, '<td valign="top">The sign looks a little washed out, unfortunately.</td>', 'The sign looks a little washed out, unfortunately.', '2005-02-05 05:14:21.000000', NULL, 1),
(1151630, 140492, 24212, '<td valign="top">Excellent lighting, but the sign is a bit too central.</td>', 'Excellent lighting, but the sign is a bit too central.', '2005-02-05 05:15:09.000000', NULL, 1),
(1151631, 142124, 24212, '<td valign="top">Very dramatic. I love the colours.</td>', 'Very dramatic. I love the colours.', '2005-02-05 05:15:53.000000', NULL, 1),
(1151633, 142421, 24212, '<td valign="top">Too much tyre and not enough sign maybe? Great idea and well lit.</td>', 'Too much tyre and not enough sign maybe? Great idea and well lit.', '2005-02-05 05:16:41.000000', NULL, 1),
(1151635, 141406, 24212, '<td valign="top">I feel that the signs should be a little sharper.</td>', 'I feel that the signs should be a little sharper.', '2005-02-05 05:17:16.000000', NULL, 1),
(1151636, 142723, 24212, '<td valign="top">Rather strangely, this picture makes me think of Sunday afternoons. Pleasant.</td>', 'Rather strangely, this picture makes me think of Sunday afternoons. Pleasant.', '2005-02-05 05:19:11.000000', NULL, 1),
(1151637, 140834, 24212, '<td valign="top">I bet car parking''s a problem around there. Lovely cool colours.</td>', 'I bet car parking''s a problem around there. Lovely cool colours.', '2005-02-05 05:20:11.000000', NULL, 1),
(1151639, 142331, 24212, '<td valign="top">You''ve captured the light here perfectly.</td>', 'You''ve captured the light here perfectly.', '2005-02-05 05:20:58.000000', NULL, 1),
(1151640, 142420, 24212, '<td valign="top">It would be nicer without the motorbike or the rubbish bags.</td>', 'It would be nicer without the motorbike or the rubbish bags.', '2005-02-05 05:22:05.000000', NULL, 1),
(1151643, 142223, 24212, '<td valign="top">Wonderfully bright. Is that really a stealth ''plane in the mirror or is it a set-up? If it''s the former, then this is a brilliant capture. If it''s the latter, it''s a brilliant set-up.</td>', 'Wonderfully bright. Is that really a stealth ''plane in the mirror or is it a set-up? If it''s the former, then this is a brilliant capture. If it''s the latter, it''s a brilliant set-up.', '2005-02-05 05:26:32.000000', NULL, 1),
(1151646, 141521, 24212, '<td valign="top">Simple and elegant. It would be nice not to be able to remove the shadow lower left, but you can''t have everything.</td>', 'Simple and elegant. It would be nice not to be able to remove the shadow lower left, but you can''t have everything.', '2005-02-05 05:28:32.000000', NULL, 1),
(1151648, 142664, 24212, '<td valign="top">Good juxtaposition between sign and sky.</td>', 'Good juxtaposition between sign and sky.', '2005-02-05 05:29:07.000000', NULL, 1),
(1151649, 142327, 24212, '<td valign="top">The sky looks a little too flat and featureless for this to really work.</td>', 'The sky looks a little too flat and featureless for this to really work.', '2005-02-05 05:29:49.000000', NULL, 1),
(1151652, 141568, 24212, '<td valign="top">Well saturated and punchy, but I feel that it would work better taken from a lower angle to leave all the extraneous background detail out.</td>', 'Well saturated and punchy, but I feel that it would work better taken from a lower angle to leave all the extraneous background detail out.', '2005-02-05 05:31:38.000000', NULL, 1),
(1151653, 142371, 24212, '<td valign="top">Very gritty.Good texture in the sign. It might be nice to see the background a little more out of focus.</td>', 'Very gritty.Good texture in the sign. It might be nice to see the background a little more out of focus.', '2005-02-05 05:33:06.000000', NULL, 1),
(1151655, 141753, 24212, '<td valign="top">Has this been a little oversharpened? There appears to be some haloing appearing around the ''30'' sign. A lovely rural feel is conveyed here, however.</td>', 'Has this been a little oversharpened? There appears to be some haloing appearing around the ''30'' sign. A lovely rural feel is conveyed here, however.', '2005-02-05 05:36:11.000000', NULL, 1),
(1151657, 142538, 3306, '<td valign="top">One of my favorites. Good job.</td>', 'One of my favorites. Good job.', '2005-02-05 05:36:32.000000', NULL, 1),
(1151658, 142732, 24212, '<td valign="top">The lighting picking out the sign is exquisite.</td>', 'The lighting picking out the sign is exquisite.', '2005-02-05 05:36:52.000000', NULL, 1),
(1151660, 142713, 24212, '<td valign="top">It would be wonderful if you could have got a bit of motion blur here.</td>', 'It would be wonderful if you could have got a bit of motion blur here.', '2005-02-05 05:37:51.000000', NULL, 1),
(1151661, 142090, 24212, '<td valign="top">The sign looks way too soft to me.</td>', 'The sign looks way too soft to me.', '2005-02-05 05:38:26.000000', NULL, 1),
(1151662, 142417, 3306, '<td valign="top">Very funny. You have a very good imagination.</td>', 'Very funny. You have a very good imagination.', '2005-02-05 05:39:17.000000', NULL, 1),
(1151663, 142360, 24212, '<td valign="top">Interesting perspective. I wonder what this photo would look like without the trees on the right.</td>', 'Interesting perspective. I wonder what this photo would look like without the trees on the right.', '2005-02-05 05:39:28.000000', NULL, 1),
(1151664, 142161, 24212, '<td valign="top">Interesting treatment. It appears, however, to have washed out the right-hand side of the pole.</td>', 'Interesting treatment. It appears, however, to have washed out the right-hand side of the pole.', '2005-02-05 05:40:54.000000', NULL, 1),
(1151666, 141839, 24212, '<td valign="top">What would have been super here would be to see that photographer chased off by an elk. Nice composition, but I''d prefer to see the photographer more out of focus.</td>', 'What would have been super here would be to see that photographer chased off by an elk. Nice composition, but I''d prefer to see the photographer more out of focus.', '2005-02-05 05:42:54.000000', NULL, 1),
(1151667, 141626, 24212, '<td valign="top">I find the uninteresting sky a bit of a distraction.</td>', 'I find the uninteresting sky a bit of a distraction.', '2005-02-05 05:43:36.000000', NULL, 1),
(1151668, 140075, 24212, '<td valign="top">Beautiful wintry lighting.</td>', 'Beautiful wintry lighting.', '2005-02-05 05:44:11.000000', NULL, 1),
(1151669, 142706, 24212, '<td valign="top">Excellent reflection, but the overexposed snow is a little off-putting. Extremely difficult lighting conditions, I know.</td>', 'Excellent reflection, but the overexposed snow is a little off-putting. Extremely difficult lighting conditions, I know.', '2005-02-05 05:45:36.000000', NULL, 1),
(1151670, 142247, 24212, '<td valign="top">The tree in the foreground is a little overpowering.</td>', 'The tree in the foreground is a little overpowering.', '2005-02-05 05:46:27.000000', NULL, 1),
(1151671, 142710, 24212, '<td valign="top">I''m sure that this is a great shot, but it''s just too small. From what I can see, the converging lines really give a sense of perspective, but as I say, too small.</td>', 'I''m sure that this is a great shot, but it''s just too small. From what I can see, the converging lines really give a sense of perspective, but as I say, too small.', '2005-02-05 05:48:12.000000', NULL, 1),
(1151672, 140988, 24212, '<td valign="top">I think that shooting this sign from a lower perspective would eliminate some of the foreground that, at present, looks like a building site.</td>', 'I think that shooting this sign from a lower perspective would eliminate some of the foreground that, at present, looks like a building site.', '2005-02-05 05:49:45.000000', NULL, 1),
(1151673, 142494, 24212, '<td valign="top">I can''t help thinking that one should never incorporate one''s own shadow in a photograph. That''s probably just my prejudices showing, then.</td>', 'I can''t help thinking that one should never incorporate one''s own shadow in a photograph. That''s probably just my prejudices showing, then.', '2005-02-05 05:51:30.000000', NULL, 1),
(1151674, 142067, 24212, '<td valign="top">I don''t know if there was anything above the sign that you needed to exclude, but putting the sign where it is in the image leaves a strange composition.</td>', 'I don''t know if there was anything above the sign that you needed to exclude, but putting the sign where it is in the image leaves a strange composition.', '2005-02-05 05:53:27.000000', NULL, 1),
(1151675, 142686, 24212, '<td valign="top">The ice looks overexposed, but the shadows in the trees are great. Very difficult lighting conditions.</td>', 'The ice looks overexposed, but the shadows in the trees are great. Very difficult lighting conditions.', '2005-02-05 05:55:14.000000', NULL, 1),
(1151677, 142574, 24212, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2005-02-05 05:55:59.000000', NULL, 1),
(1151678, 140989, 24212, '<td valign="top">The sign is perhaps a little too central and it would be nice to lose the neon sign behind. (I know, editing rules forbid it)</td>', 'The sign is perhaps a little too central and it would be nice to lose the neon sign behind. (I know, editing rules forbid it)', '2005-02-05 05:58:07.000000', NULL, 1),
(1151682, 141610, 24212, '<td valign="top">I can''t help feelling that you were hampered here by the rotten light of an overcast day.</td>', 'I can''t help feelling that you were hampered here by the rotten light of an overcast day.', '2005-02-05 06:00:31.000000', NULL, 1),
(1151683, 142486, 24212, '<td valign="top">A pity about the buildings behind the bridge. They detract from the clean lines you''d get otherwise.</td>', 'A pity about the buildings behind the bridge. They detract from the clean lines you''d get otherwise.', '2005-02-05 06:01:57.000000', NULL, 1),
(1151689, 141244, 24212, '<td valign="top">To me, neither the sign nor the chimneys are vertical, so they seem to be falling together. If the photo were to be rotated,so thay the chimneys were vertical, then the sign would seem to lean towards the chimneys as if to ram its message home. It would also be good if you could give the sign a saturation boost to give it a little more punch.</td>', 'To me, neither the sign nor the chimneys are vertical, so they seem to be falling together. If the photo were to be rotated,so thay the chimneys were vertical, then the sign would seem to lean towards the chimneys as if to ram its message home. It would also be good if you could give the sign a saturation boost to give it a little more punch.', '2005-02-05 06:06:29.000000', NULL, 1),
(1151691, 142438, 24212, '<td valign="top">I like the colour treatment here. It looks as if the figure is holding onto the stick.</td>', 'I like the colour treatment here. It looks as if the figure is holding onto the stick.', '2005-02-05 06:07:29.000000', NULL, 1),
(1151694, 141151, 24212, '<td valign="top">Unfortunately, the sign looks too eroded to have a lot of impact against the ''phone booths. It looks as if the focus is on the vehicle rather than the foreground.</td>', 'Unfortunately, the sign looks too eroded to have a lot of impact against the ''phone booths. It looks as if the focus is on the vehicle rather than the foreground.', '2005-02-05 06:10:27.000000', NULL, 1),
(1151696, 142498, 24212, '<td valign="top">I went out looking for signs that were lost in hedges or otherwise overgrown and found nothing as good as this.</td>', 'I went out looking for signs that were lost in hedges or otherwise overgrown and found nothing as good as this.', '2005-02-05 06:11:43.000000', NULL, 1),
(1151699, 142193, 24212, '<td valign="top">Is this really a road sign? A pleasant shot, but the buildings visible through the trees kill off the impression of isolation.</td>', 'Is this really a road sign? A pleasant shot, but the buildings visible through the trees kill off the impression of isolation.', '2005-02-05 06:13:15.000000', NULL, 1),
(1151704, 141279, 31175, '<td valign="top">Too small; it would be nice to see more detail</td>', 'Too small; it would be nice to see more detail', '2005-02-05 06:30:26.000000', NULL, 1),
(1151705, 141845, 31175, '<td valign="top">A touch more contrast would help</td>', 'A touch more contrast would help', '2005-02-05 06:33:41.000000', NULL, 1),
(1151706, 141151, 23251, '<td valign="top">Yes I can Bruce.....  or Kirsty... or Brett..  lol</td>', 'Yes I can Bruce.....  or Kirsty... or Brett..  lol', '2005-02-05 06:38:06.000000', NULL, 1),
(1151707, 142710, 31175, '<td valign="top">Much too small to judge. Needs to be sized properly.</td>', 'Much too small to judge. Needs to be sized properly.', '2005-02-05 06:39:14.000000', NULL, 1),
(1151708, 142247, 23251, '<td valign="top">Sorry but its not a road sign.  Great photo though.</td>', 'Sorry but its not a road sign.  Great photo though.', '2005-02-05 06:40:27.000000', NULL, 1),
(1151709, 140612, 31175, '<td valign="top">I can''t connect this picture with Road Signs</td>', 'I can''t connect this picture with Road Signs', '2005-02-05 06:45:14.000000', NULL, 1),
(1151711, 140899, 23251, '<td valign="top">THTC  relief  lol....  Turtle head touching cloth</td>', 'THTC  relief  lol....  Turtle head touching cloth', '2005-02-05 06:48:16.000000', NULL, 1),
(1151712, 142419, 24212, '<td valign="top">This all looks a little dark to me.</td>', 'This all looks a little dark to me.', '2005-02-05 06:52:49.000000', NULL, 1),
(1151714, 142675, 24212, '<td valign="top">The sign looks a little soft on my screen.</td>', 'The sign looks a little soft on my screen.', '2005-02-05 06:53:24.000000', NULL, 1),
(1151715, 142104, 24212, '<td valign="top">A good feeling of solitude here and great texture in the trees.</td>', 'A good feeling of solitude here and great texture in the trees.', '2005-02-05 06:54:04.000000', NULL, 1),
(1151716, 142204, 24212, '<td valign="top">I think that the sign should be a bit more brightly lit.</td>', 'I think that the sign should be a bit more brightly lit.', '2005-02-05 06:54:55.000000', NULL, 1),
(1151717, 140975, 24212, '<td valign="top">I think that perhaps the fill flash is a little overdone, but there is a nice contrast between the simplicity of the lines of the sign and the complexity of the clouds. I''m not sure about cropping the bottom left of the sign, though.</td>', 'I think that perhaps the fill flash is a little overdone, but there is a nice contrast between the simplicity of the lines of the sign and the complexity of the clouds. I''m not sure about cropping the bottom left of the sign, though.', '2005-02-05 06:57:12.000000', NULL, 1),
(1151720, 141144, 23251, '<td valign="top">Good use of a filter to create a unnatural feeling.  Well done.</td>', 'Good use of a filter to create a unnatural feeling.  Well done.', '2005-02-05 06:58:25.000000', NULL, 1),
(1151721, 142205, 23251, '<td valign="top">Pity the focus was not sharp and the tip of the arrow is not in the shot.  Good capture though.</td>', 'Pity the focus was not sharp and the tip of the arrow is not in the shot.  Good capture though.', '2005-02-05 07:00:27.000000', NULL, 1),
(1151722, 142318, 24212, '<td valign="top">You''ve captured the sun appearing over the sign very well here.</td>', 'You''ve captured the sun appearing over the sign very well here.', '2005-02-05 07:00:37.000000', NULL, 1),
(1151723, 142737, 24212, '<td valign="top">Very bleak, although the crash barrier below the sign is a little uninvolving.</td>', 'Very bleak, although the crash barrier below the sign is a little uninvolving.', '2005-02-05 07:01:45.000000', NULL, 1),
(1151724, 142717, 23251, '<td valign="top">Sorry but this really has nothing to do with road signs.  Its a good capture although its some what out of focus.</td>', 'Sorry but this really has nothing to do with road signs.  Its a good capture although its some what out of focus.', '2005-02-05 07:02:09.000000', NULL, 1),
(1151725, 141788, 24212, '<td valign="top">This doesn''t look as sharp as it possibly could be. I like the framing.</td>', 'This doesn''t look as sharp as it possibly could be. I like the framing.', '2005-02-05 07:02:40.000000', NULL, 1),
(1151726, 141972, 24212, '<td valign="top">The signs could, I feel, be a bit sharper.</td>', 'The signs could, I feel, be a bit sharper.', '2005-02-05 07:03:20.000000', NULL, 1),
(1151727, 141516, 23251, '<td valign="top">I think this could have done very well without the wierd border effect that you have created.   The subject was already unique.</td>', 'I think this could have done very well without the wierd border effect that you have created.   The subject was already unique.', '2005-02-05 07:04:42.000000', NULL, 1),
(1151728, 142717, 24212, '<td valign="top">I''m sorry, but I can''t get road signs here. It all seems a bit too out of focus and lacking direction.</td>', 'I''m sorry, but I can''t get road signs here. It all seems a bit too out of focus and lacking direction.', '2005-02-05 07:04:43.000000', NULL, 1),
(1151729, 142668, 24212, '<td valign="top">Excellent framing. The best stop sign shot I''ve seen in this challenge so far.</td>', 'Excellent framing. The best stop sign shot I''ve seen in this challenge so far.', '2005-02-05 07:05:40.000000', NULL, 1),
(1151730, 141631, 24212, '<td valign="top">The sign really seems to be shouting its message. Dramatic sky really works well.</td>', 'The sign really seems to be shouting its message. Dramatic sky really works well.', '2005-02-05 07:06:45.000000', NULL, 1),
(1151731, 142333, 30712, '<td valign="top">The drama of this image makes it the best.  It has that wow! factor.</td>', 'The drama of this image makes it the best.  It has that wow! factor.', '2005-02-05 07:07:52.000000', NULL, 1),
(1151732, 141152, 23251, '<td valign="top">Ok let me guess,  Kirsty?  Right?</td>', 'Ok let me guess,  Kirsty?  Right?', '2005-02-05 07:08:01.000000', NULL, 1),
(1151733, 142625, 24212, '<td valign="top">Unfortunately, this shot seems to be affected by camera shake. The dark object in the lower left corner draws the eye away from the sign.</td>', 'Unfortunately, this shot seems to be affected by camera shake. The dark object in the lower left corner draws the eye away from the sign.', '2005-02-05 07:08:29.000000', NULL, 1),
(1151735, 142321, 24212, '<td valign="top">I think that cropping out the foreground would lend more impact.The main subject seems to be floating in the middle of the picture.</td>', 'I think that cropping out the foreground would lend more impact.The main subject seems to be floating in the middle of the picture.', '2005-02-05 07:10:09.000000', NULL, 1),
(1151736, 141859, 24212, '<td valign="top">The lighting on the centre of the sign seems a little too harsh, which detracts from the impact of the image.</td>', 'The lighting on the centre of the sign seems a little too harsh, which detracts from the impact of the image.', '2005-02-05 07:11:27.000000', NULL, 1),
(1151737, 142348, 30712, '<td valign="top">I love the simplicity of this scene.  Without the snow the ties between the posts would be an eyesore but the white droop of the pathetic barrier adds extra tension to the image.</td>', 'I love the simplicity of this scene.  Without the snow the ties between the posts would be an eyesore but the white droop of the pathetic barrier adds extra tension to the image.', '2005-02-05 07:11:49.000000', NULL, 1),
(1151740, 141703, 30712, '<td valign="top">There have been so many signs in the sky images but the background to this image adds quality to the picture.  A plain sky background would have pushed the scene right down the list.</td>', 'There have been so many signs in the sky images but the background to this image adds quality to the picture.  A plain sky background would have pushed the scene right down the list.', '2005-02-05 07:14:14.000000', NULL, 1),
(1151741, 141144, 30712, '<td valign="top">An image that shouts, "Look at me!"</td>', 'An image that shouts, "Look at me!"', '2005-02-05 07:15:24.000000', NULL, 1),
(1151743, 142360, 30712, '<td valign="top">What a difference the angle of view makes.</td>', 'What a difference the angle of view makes.', '2005-02-05 07:16:15.000000', NULL, 1),
(1151750, 142466, 24212, '<td valign="top">Clever treatment of colour here.</td>', 'Clever treatment of colour here.', '2005-02-05 07:28:46.000000', NULL, 1),
(1151751, 141475, 24212, '<td valign="top">This doesn''t scream ''road sign'' at me, but it''s a great picture that draws the eye in.</td>', 'This doesn''t scream ''road sign'' at me, but it''s a great picture that draws the eye in.', '2005-02-05 07:30:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1151753, 140907, 24212, '<td valign="top">Amusing, but it''s not a particularly attractive sign. It looks a bit makeshift.</td>', 'Amusing, but it''s not a particularly attractive sign. It looks a bit makeshift.', '2005-02-05 07:32:03.000000', NULL, 1),
(1151754, 142121, 24212, '<td valign="top">To me, the sign looks as though it could be a little brighter.</td>', 'To me, the sign looks as though it could be a little brighter.', '2005-02-05 07:32:51.000000', NULL, 1),
(1151755, 142444, 24212, '<td valign="top">Very unusual. I must confess that I had to sit looking at it for a minute in order to see the sign.</td>', 'Very unusual. I must confess that I had to sit looking at it for a minute in order to see the sign.', '2005-02-05 07:34:01.000000', NULL, 1),
(1151757, 142246, 24212, '<td valign="top">Lovely bright, striking image, but perhaps not enough road sign, if you get what I mean.</td>', 'Lovely bright, striking image, but perhaps not enough road sign, if you get what I mean.', '2005-02-05 07:35:29.000000', NULL, 1),
(1151759, 141971, 24212, '<td valign="top">It''s a pity that the fence is there. It looks as though some of the snow is overexposed. Very difficult lighting conditions, I would guess.</td>', 'It''s a pity that the fence is there. It looks as though some of the snow is overexposed. Very difficult lighting conditions, I would guess.', '2005-02-05 07:37:13.000000', NULL, 1),
(1151762, 141152, 24212, '<td valign="top">Perhaps it would have been better to photograph the sign more square on, so that the lines around the edges of the sign align with the edges of the photo.</td>', 'Perhaps it would have been better to photograph the sign more square on, so that the lines around the edges of the sign align with the edges of the photo.', '2005-02-05 07:39:07.000000', NULL, 1),
(1151764, 142198, 24212, '<td valign="top">Interesting, but I feel that this would have even more impact if the sign were sharper and a touch brighter.</td>', 'Interesting, but I feel that this would have even more impact if the sign were sharper and a touch brighter.', '2005-02-05 07:40:25.000000', NULL, 1),
(1151765, 141225, 24212, '<td valign="top">The cropping off of the poster on the left leaves the picture feeling a little unfinished to me.</td>', 'The cropping off of the poster on the left leaves the picture feeling a little unfinished to me.', '2005-02-05 07:41:38.000000', NULL, 1),
(1151768, 141144, 24212, '<td valign="top">The lighting balance is spot-on here. The brightness of the sign sits very well with the angriness of the sky.</td>', 'The lighting balance is spot-on here. The brightness of the sign sits very well with the angriness of the sky.', '2005-02-05 07:43:09.000000', NULL, 1),
(1151770, 142458, 24212, '<td valign="top">I think that the cyclist on the right needs to be a little brighter to balance the image a little better. It looks as though the snow in the bottom right was a bit overexposed.</td>', 'I think that the cyclist on the right needs to be a little brighter to balance the image a little better. It looks as though the snow in the bottom right was a bit overexposed.', '2005-02-05 07:45:04.000000', NULL, 1),
(1151772, 142205, 24212, '<td valign="top">This sign is way too soft or blurry. Maybe a little sharpening would help.</td>', 'This sign is way too soft or blurry. Maybe a little sharpening would help.', '2005-02-05 07:46:30.000000', NULL, 1),
(1151773, 142509, 24212, '<td valign="top">Good texture in the sign and nicely out of focus background.</td>', 'Good texture in the sign and nicely out of focus background.', '2005-02-05 07:47:22.000000', NULL, 1),
(1151774, 142600, 24212, '<td valign="top">Quite a high-key look here, which works really well.</td>', 'Quite a high-key look here, which works really well.', '2005-02-05 07:48:10.000000', NULL, 1),
(1151776, 141470, 24212, '<td valign="top">To me, this image is a little too busy. Nicely sharp though.</td>', 'To me, this image is a little too busy. Nicely sharp though.', '2005-02-05 07:49:21.000000', NULL, 1),
(1151778, 142131, 24212, '<td valign="top">I think that the sign is a little too faded to make this shot really work. Perhaps boosting the yellow channel might help.</td>', 'I think that the sign is a little too faded to make this shot really work. Perhaps boosting the yellow channel might help.', '2005-02-05 07:50:36.000000', NULL, 1),
(1151786, 141295, 24212, '<td valign="top">The signs are a little dark to really grab my attention.</td>', 'The signs are a little dark to really grab my attention.', '2005-02-05 08:02:16.000000', NULL, 1),
(1151795, 141144, 14369, '<td valign="top">Love the colors in this...the contrast really brings out the sign! Great photo!<br/> <br/></td>', 'Love the colors in this...the contrast really brings out the sign! Great photo! ', '2005-02-05 08:06:47.000000', NULL, 1),
