(1153025, 141309, 14028, '<td valign="top">he he! that''s a cool shot.and the blurred car is great too.</td>', 'he he! that''s a cool shot.and the blurred car is great too.', '2005-02-06 06:55:30.000000', NULL, 1),
(1153027, 141838, 14028, '<td valign="top">thats an excellent iconic location.the comp[osition of the shot is not bad.however i think you should get the "one way" sign in focus as it should be the central subject</td>', 'thats an excellent iconic location.the comp[osition of the shot is not bad.however i think you should get the "one way" sign in focus as it should be the central subject', '2005-02-06 07:02:24.000000', NULL, 1),
(1153035, 142405, 28367, '<td valign="top">I like the idea, but i think the crop is a bit too tight or the angle is too forward.</td>', 'I like the idea, but i think the crop is a bit too tight or the angle is too forward.', '2005-02-06 07:15:51.000000', NULL, 1),
