(1154849, 142108, 4267, '<td valign="top">bikes don;t belong on the road.. lol I honk incessently at bikers.. they are a traffic hazrd to everyone.... but nice photo</td>', 'bikes don;t belong on the road.. lol I honk incessently at bikers.. they are a traffic hazrd to everyone.... but nice photo', '2005-02-07 11:41:03.000000', NULL, 1),
(1154855, 140904, 4267, '<td valign="top">looks like he missed the power and ran the stop sign... lol nice capture with the ghosting technique.. good placement of the sign.. good color and light levels..</td>', 'looks like he missed the power and ran the stop sign... lol nice capture with the ghosting technique.. good placement of the sign.. good color and light levels..', '2005-02-07 11:42:40.000000', NULL, 1),
(1154936, 141299, 19780, '<td valign="top">Beautiful colors and variety - I really like the centered composition with the sign smack in the middle because it brings order to the chaotic colors and shapes. You get a 10 from me.</td>', 'Beautiful colors and variety - I really like the centered composition with the sign smack in the middle because it brings order to the chaotic colors and shapes. You get a 10 from me.', '2005-02-07 12:34:59.000000', NULL, 1),
(1154937, 142673, 16106, '<td valign="top">great colors but a bit of flash on the sign would have put this near the top</td>', 'great colors but a bit of flash on the sign would have put this near the top', '2005-02-07 12:35:43.000000', NULL, 1),
(1154938, 142331, 19780, '<td valign="top">Stunning capture. The sky and low clouds are perfect as is the composition. I wish the sign were a little clearer/sharper. 9</td>', 'Stunning capture. The sky and low clouds are perfect as is the composition. I wish the sign were a little clearer/sharper. 9', '2005-02-07 12:35:58.000000', NULL, 1),
(1154941, 141982, 19780, '<td valign="top">Wonderful capture. I love the colors and crispness. The pole is a little overexposed, but then again, I''d like the sign to have a little better contrast (basic editing rules, I understand). Really fun composition. 8</td>', 'Wonderful capture. I love the colors and crispness. The pole is a little overexposed, but then again, I''d like the sign to have a little better contrast (basic editing rules, I understand). Really fun composition. 8', '2005-02-07 12:37:23.000000', NULL, 1),
(1154983, 142717, 16301, '<td valign="top">Are you sure you''re in the right challenge?</td>', 'Are you sure you''re in the right challenge?', '2005-02-07 12:57:38.000000', NULL, 1),
(1154992, 142461, 6532, '<td valign="top">The bright lights on the signs make them hard to read.  Cool grab of the trailing lights...</td>', 'The bright lights on the signs make them hard to read.  Cool grab of the trailing lights...', '2005-02-07 13:01:54.000000', NULL, 1),
(1154994, 141864, 6532, '<td valign="top">I think this may have worked better if the light was totally hidden behind the sign.</td>', 'I think this may have worked better if the light was totally hidden behind the sign.', '2005-02-07 13:02:29.000000', NULL, 1),
(1154995, 141209, 6532, '<td valign="top">A more drastic angle showing more of the road would have been more effective - IMO.  Contrast is a bit shallow as well.</td>', 'A more drastic angle showing more of the road would have been more effective - IMO.  Contrast is a bit shallow as well.', '2005-02-07 13:03:13.000000', NULL, 1),
