(1155014, 142184, 2798, '<td valign="top">I like the grain and slightly false colours. Good atmosphere and choice of road sign. 7</td>', 'I like the grain and slightly false colours. Good atmosphere and choice of road sign. 7', '2005-02-07 13:14:26.000000', NULL, 1),
(1155016, 141631, 6532, '<td valign="top">Nice!</td>', 'Nice!', '2005-02-07 13:14:58.000000', NULL, 1),
(1155019, 141972, 2798, '<td valign="top">I guess the S sign means no stopping. I''m a brit so this image only works if you''re american. Otherwise an acceptable exposure and quite a tight crop. I would have liked it less tight. 6</td>', 'I guess the S sign means no stopping. I''m a brit so this image only works if you''re american. Otherwise an acceptable exposure and quite a tight crop. I would have liked it less tight. 6', '2005-02-07 13:16:12.000000', NULL, 1),
(1155021, 140621, 2798, '<td valign="top">I find the lack of focus at the bottom unsettling. Nice reflection in the mirror but I''m not sure what it reallly brings to the image. 6</td>', 'I find the lack of focus at the bottom unsettling. Nice reflection in the mirror but I''m not sure what it reallly brings to the image. 6', '2005-02-07 13:17:30.000000', NULL, 1),
(1155026, 142367, 2798, '<td valign="top">This image seems excessively jpegd. It''s very hard to read the signs as a result. Jpg artifacts are also visible on the darker tree branches. You have some nice colour in the bottom right. I think a little more post processing might have brought that up and improved the interest. 6</td>', 'This image seems excessively jpegd. It''s very hard to read the signs as a result. Jpg artifacts are also visible on the darker tree branches. You have some nice colour in the bottom right. I think a little more post processing might have brought that up and improved the interest. 6', '2005-02-07 13:19:45.000000', NULL, 1),
(1155028, 142675, 2798, '<td valign="top">Shame about the shadow in the bottom left. Otherwise good. 6</td>', 'Shame about the shadow in the bottom left. Otherwise good. 6', '2005-02-07 13:20:42.000000', NULL, 1),
(1155032, 142474, 2798, '<td valign="top">Looks like a small crop from a large image. Very visible noise in the blue areas and strong evidence of sharpening. Otherwise a fun choice of subject. 6</td>', 'Looks like a small crop from a large image. Very visible noise in the blue areas and strong evidence of sharpening. Otherwise a fun choice of subject. 6', '2005-02-07 13:22:05.000000', NULL, 1),
(1155037, 141834, 6532, '<td valign="top">If only you could have shot a different perspective to eliminate the buildings and possibly show the road.....</td>', 'If only you could have shot a different perspective to eliminate the buildings and possibly show the road.....', '2005-02-07 13:22:22.000000', NULL, 1),
(1155038, 142625, 2798, '<td valign="top">Just slightly suspect focus lets this down. Otherwise excellent. 7</td>', 'Just slightly suspect focus lets this down. Otherwise excellent. 7', '2005-02-07 13:23:09.000000', NULL, 1),
(1155039, 140834, 2798, '<td valign="top">Nice light. I think I would have liked more room at the top. 8</td>', 'Nice light. I think I would have liked more room at the top. 8', '2005-02-07 13:24:17.000000', NULL, 1),
(1155042, 141309, 6532, '<td valign="top">More common than a stop sign, more powerful than a red light....what an original capture!</td>', 'More common than a stop sign, more powerful than a red light....what an original capture!', '2005-02-07 13:25:43.000000', NULL, 1),
(1155045, 141629, 2798, '<td valign="top">Impressive view and a wonderful sign. Well done. 9</td>', 'Impressive view and a wonderful sign. Well done. 9', '2005-02-07 13:25:54.000000', NULL, 1),
(1155052, 141244, 2798, '<td valign="top">An excellently composed and concieved image spoiled by very bad white balance and an excess of exclamation points. A little work in a graphics package to correct the white balance, lighten and increase contrast would hugely improve this image. This would be a 9 once edited. For now it''s a 7.</td>', 'An excellently composed and concieved image spoiled by very bad white balance and an excess of exclamation points. A little work in a graphics package to correct the white balance, lighten and increase contrast would hugely improve this image. This would be a 9 once edited. For now it''s a 7.', '2005-02-07 13:28:00.000000', NULL, 1),
(1155054, 142563, 2798, '<td valign="top">Nice light and contast. A good simple capture. 9.</td>', 'Nice light and contast. A good simple capture. 9.', '2005-02-07 13:28:40.000000', NULL, 1),
(1155057, 142107, 6532, '<td valign="top">Cropping is a bit too tight!</td>', 'Cropping is a bit too tight!', '2005-02-07 13:29:21.000000', NULL, 1),
(1155062, 141214, 2798, '<td valign="top">A good idea but not a great crop. Needs to be bigger and with the sign more towards the top of the frame. Also a fill-flash would have put more light on the ball and the sign while keeping the nicely exposed sky. 7</td>', 'A good idea but not a great crop. Needs to be bigger and with the sign more towards the top of the frame. Also a fill-flash would have put more light on the ball and the sign while keeping the nicely exposed sky. 7', '2005-02-07 13:30:02.000000', NULL, 1),
(1155064, 140883, 2798, '<td valign="top">Simple, atmospheric and beautifiul. 9</td>', 'Simple, atmospheric and beautifiul. 9', '2005-02-07 13:30:34.000000', NULL, 1),
(1155066, 141299, 2798, '<td valign="top">Love it. Well composed and a great choice of subject. 9</td>', 'Love it. Well composed and a great choice of subject. 9', '2005-02-07 13:31:05.000000', NULL, 1),
