INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1155389, 141384, 19594, '<td valign="top">not a good picture. blurry.  too dark. doesn''t say anything photo worthy.</td>', 'not a good picture. blurry.  too dark. doesn''t say anything photo worthy.', '2005-02-07 16:06:38.000000', NULL, 1),
(1155393, 141244, 28108, '<td valign="top">Political message? Neat. I like it.</td>', 'Political message? Neat. I like it.', '2005-02-07 16:08:30.000000', NULL, 1),
(1155420, 142717, 27845, '<td valign="top">This picture doesn''t meet the challenge. It has absolutely no link to a road sign, or even to any other sign. Did you mix it up with another challenge? What''s more, it''s out of focus. Really blurry. Maybe the macro mode on your camera would have helped your cam to focus on the subject. The flash you used creates quite a harsh lighting. There''s a bright highlight on the apple and a hard shadow under the kitten. I don''t understand your choice for the crop either. You cut both the cat''s eye and paw off. I hope this helps you for your next shot. For this picture however, I have to give you a 1.</td>', 'This picture doesn''t meet the challenge. It has absolutely no link to a road sign, or even to any other sign. Did you mix it up with another challenge? What''s more, it''s out of focus. Really blurry. Maybe the macro mode on your camera would have helped your cam to focus on the subject. The flash you used creates quite a harsh lighting. There''s a bright highlight on the apple and a hard shadow under the kitten. I don''t understand your choice for the crop either. You cut both the cat''s eye and paw off. I hope this helps you for your next shot. For this picture however, I have to give you a 1.', '2005-02-07 16:23:42.000000', NULL, 1),
(1155423, 142668, 27845, '<td valign="top">Bang! Great impact. The sign is straight in my face, as if I had stopped "just in time". I also like the sharpness, the saturation and the screws. Very simple and striking. 10.</td>', 'Bang! Great impact. The sign is straight in my face, as if I had stopped "just in time". I also like the sharpness, the saturation and the screws. Very simple and striking. 10.', '2005-02-07 16:26:16.000000', NULL, 1),
(1155427, 141788, 27845, '<td valign="top">Cool signs. They make up a good picture. It just lacks some sharpness. 7.</td>', 'Cool signs. They make up a good picture. It just lacks some sharpness. 7.', '2005-02-07 16:28:29.000000', NULL, 1),
(1155433, 142328, 33317, '<td valign="top">abstract and confusing. what/where is the subject?</td>', 'abstract and confusing. what/where is the subject?', '2005-02-07 16:33:12.000000', NULL, 1),
(1155435, 141214, 33317, '<td valign="top">creative. is the football stopping for  the sign? fluffy clouds. sign is not red enough (touch-up or filter may help?)</td>', 'creative. is the football stopping for  the sign? fluffy clouds. sign is not red enough (touch-up or filter may help?)', '2005-02-07 16:34:14.000000', NULL, 1),
(1155438, 142473, 27845, '<td valign="top">Hard to tell beacuse the image is so small. Submit a larger image next time! 3.</td>', 'Hard to tell beacuse the image is so small. Submit a larger image next time! 3.', '2005-02-07 16:36:07.000000', NULL, 1),
(1155439, 142320, 33317, '<td valign="top">good composure, except the tree trunk is distracting. repetition of two people on sign and the kids. I wonder if a more open aperture would have helped - the forest is in good focus and detracts from the kids and signs.</td>', 'good composure, except the tree trunk is distracting. repetition of two people on sign and the kids. I wonder if a more open aperture would have helped - the forest is in good focus and detracts from the kids and signs.', '2005-02-07 16:36:42.000000', NULL, 1),
(1155441, 141523, 33317, '<td valign="top">vivid, good composition.</td>', 'vivid, good composition.', '2005-02-07 16:37:18.000000', NULL, 1),
