(1156684, 142037, 30364, '<td valign="top">Great composition gives the sign tremendous presence; it''s a critical part of the image, not just a sign in a picture.  Very nice quality photography &amp; processing, too.  8.</td>', 'Great composition gives the sign tremendous presence; it''s a critical part of the image, not just a sign in a picture.  Very nice quality photography & processing, too.  8.', '2005-02-08 03:03:27.000000', NULL, 1),
(1156702, 141475, 30364, '<td valign="top">A very clever idea, effortlessly executed.  Sure sign of an imaginative and confident photographer.  Absolutely no suggestions for improvement.  Top three for me.  9.</td>', 'A very clever idea, effortlessly executed.  Sure sign of an imaginative and confident photographer.  Absolutely no suggestions for improvement.  Top three for me.  9.', '2005-02-08 03:13:09.000000', NULL, 1),
